INSERT INTO blobs VALUES ('c6c3240dd0647986b459c34b64021c1f5d651483c2f781ba2e20d043fcff35f4', '{"content":[{"result":"---\nname: icp-outreach\ndescription: Research, qualify, draft, execute, and reconcile evidence-gated B2B outreach for Telara across LinkedIn, Notion, Gmail, and public company sources. Use when finding ICPs or security leaders, assessing accepted connections or non-response, drafting connection notes, messages, emails, or meeting follow-ups, checking replies, sending a user-approved batch, or updating the Telara CRM.\n---\n\n# ICP outreach\n\nRun a truth-gated outreach loop. Research, drafts, sends, receipts, and CRM writes are different states. Never collapse them.\n\n    10|Read [Operating contract](references/operating-contract.md) before any external research, draft, send, or CRM update. Read [CRM contract](references/crm-reconciliation.md) before touching Notion.\n\n## 1. Establish the motion\n\n- Classify the request as research, drafting, send execution, reply handling, non-response analysis, or CRM hygiene.\n- Treat research and drafting as read-only. Do not send, invite, react, follow, schedule, or mutate Notion unless the user explicitly authorizes that action in the current turn.\n- For a batch, keep the full roster in scope. Finish with every person marked sent, skipped with a precise reason, or blocked by a specific missing input.\n- Keep public-comment monitoring separate from private outreach. A public engagement never authorizes a connection request, message, or email.\n\n## 2. Build a truth record before qualifying\n    20|\nFor each person, collect facts separately from inferences:\n\n| Area | Required proof |\n| --- | --- |\n| Person | Full name, canonical LinkedIn URL, current title, current employer, and role in the buying process |\n| Account | Operating-company status, current company/product context, size or scale signal, geography when relevant, and competitor or adjacency classification |\n| Problem | One observed trigger involving multiple agent clients, shared systems, delegated access, consequential actions, approvals, audit, revocation, cost, or ownership |\n| R…","toolCallId":"call-327a82c4-9c7e-48b2-822e-fe63ac449b09-4\nfc_6a218010-40d9-9d9c-bb13-e6aaa5727589_1","toolName":"Read","type":"tool-result"}],"id":"call-327a82c4-9c7e-48b2-822e-fe63ac449b09-4\nfc_6a218010-40d9-9d9c-bb13-e6aaa5727589_1","role":"tool"}');
