INSERT INTO blobs VALUES ('f2b3bedb6b37b02f26c6ab3b6d26a05d401570ee43a6637965372ded03a16201', '{"content":[{"result":"#!/bin/bash\n\n# --- DEFAULTS ---\nPROTO_BRANCH=\"main\"\nUTIL_BRANCH=\"main\"\nAUDIT_BRANCH=\"main\"\n\n# --- HELPER FUNCTIONS ---\ninfo() {\n    10|    echo\n    echo \"#################################################################\"\n    echo \"## $1\"\n    echo \"#################################################################\"\n    echo\n}\n\nusage() {\n    echo \"Usage: $(basename \"$0\") [options]\"\n    echo\n    20|    echo \"This script builds, deploys, and configures the telara-middleware services.\"\n    echo\n    echo \"Options:\"\n    echo \"  --proto-branch, -pb <branch> Update the protobuf definitions for all modules.\"\n    echo \"  --util-branch, -ub <branch> Update the utilities for all modules.\"\n    echo \"  --audit-branch, -ab <branch> Update the audit service for all modules.\"\n    echo \"  -h, --help              Display this help message.\"\n    exit 1\n}\n\n    30|# --- ARGUMENT PARSING ---\nwhile [[ \"$#\" -gt 0 ]]; do\n    case $1 in\n        --proto-branch|-pb) PROTO_BRANCH=\"$2\"; shift ;;\n        --util-branch|-ub) UTIL_BRANCH=\"$2\"; shift ;;\n        --audit-branch|-ab) AUDIT_BRANCH=\"$2\"; shift ;;\n        -h|--help) usage ;;\n        *) echo \"Unknown parameter passed: $1\"; usage ;;\n    esac\n    shift\n    40|done\n\nmod_pids=()\nmod_logs=()\nmod_dirs=()\n\nwhile IFS= read -r -d $''\\0'' file; do\n  mod_log=$(mktemp)\n  (\n    cd \"$(dirname \"$file\")\" || exit 1\n    50|    # if telara module is in the file, then run the update-proto.sh script\n    if grep -q \"gitlab.com/telara-labs\" \"go.mod\"; then\n      echo \"================================================\"\n      echo \"Checking for updates in: $(pwd)\"\n      echo \"================================================\"\n       # OK -  Updating module: gitlab.com/telara-labs/telara-utilities/go/security\n       # NOT OK - Updating module: v0.0.0-20250714231219-3fded3728ec2\n      # for each telara gitlab module - update the module to the main branch\n      get_rc=0\n      # TENG-2251: the grep below also matches this go.mod''s own `module` line,\n    60|      # and `go get …","toolCallId":"call-8c0e6cf8-9946-465e-b421-00d7c31e98ac-48\nfc_7aa4d532-9eb1-9bb6-aa17-fa9be085df53_3","toolName":"Read","type":"tool-result"}],"id":"call-8c0e6cf8-9946-465e-b421-00d7c31e98ac-48\nfc_7aa4d532-9eb1-9bb6-aa17-fa9be085df53_3","role":"tool"}');
